-- Athena saved query (Product_B2C_Intl)
-- ID: d68afc5e-7239-46ef-9c20-b361a94d9e02
-- Name: Cohorted Deal Order and Click Share Final - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp_base AS ( SELECT s.mri_session_id, s.route_id, CAST(s.doj AS VARCHAR) AS doj, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, CASE WHEN s.cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END AS is_boosted_route FROM user_interaction.search_route_details s WHERE __time >= TIMESTAMP '2026-04-23 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 AND s.country = 'IND' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'iOS' AND s.tp_channel = 'INVALID' ), -- ✅ Session level session_flags AS ( SELECT mri_session_id, MAX(exp_variant) AS exp_variant, MAX(is_boosted_route) AS saw_boost FROM srp_base GROUP BY 1 ), -- ✅ Variant-level offer tuples (IMPORTANT CHANGE) offer_tuples AS ( SELECT DISTINCT exp_variant, route_id, doj FROM srp_base WHERE is_boosted_route = 1 ), -- SL sl_base AS ( SELECT DISTINCT mri_session_id, route_id, CAST(doj AS VARCHAR) AS doj FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-04-23 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND country = 'IND' ), -- Confirm confirm_base AS ( SELECT DISTINCT mri_session_id, route_id, CAST(doj AS VARCHAR) AS doj FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-04-23 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') ), -- Combine SL + Confirm at route level combined AS ( SELECT sf.exp_variant, sf.saw_boost, sl.mri_session_id, sl.route_id, sl.doj, CASE WHEN c.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS has_confirm FROM session_flags sf LEFT JOIN sl_base sl ON sf.mri_session_id = sl.mri_session_id LEFT JOIN confirm_base c ON sl.mri_session_id = c.mri_session_id AND sl.route_id = c.route_id AND sl.doj = c.doj ), -- Tag offer tuples at VARIANT LEVEL final AS ( SELECT c.*, CASE WHEN ot.route_id IS NOT NULL THEN 1 ELSE 0 END AS is_offer_tuple FROM combined c LEFT JOIN offer_tuples ot ON c.exp_variant = ot.exp_variant AND c.route_id = ot.route_id AND c.doj = ot.doj ) SELECT 'April 24 to 29' month_period, exp_variant, -- 1. Boost seen → SL COUNT(DISTINCT CASE WHEN saw_boost = 1 THEN mri_session_id END) AS boost_seen_sl, -- 2. Boost seen → Confirm COUNT(DISTINCT CASE WHEN saw_boost = 1 AND has_confirm = 1 THEN mri_session_id END) AS boost_seen_confirm, -- 3. Overall SL COUNT(DISTINCT mri_session_id) AS overall_sl, -- 4. Overall Confirm COUNT(DISTINCT CASE WHEN has_confirm = 1 THEN mri_session_id END) AS overall_confirm, -- 5. Offer tuple SL (variant-level) COUNT(DISTINCT CASE WHEN is_offer_tuple = 1 THEN mri_session_id END) AS offer_tuple_sl, -- 6. Offer tuple Confirm COUNT(DISTINCT CASE WHEN is_offer_tuple = 1 AND has_confirm = 1 THEN mri_session_id END) AS offer_tuple_confirm, -- 7. Boosted offer tuple SL (intersection) COUNT(DISTINCT CASE WHEN saw_boost = 1 AND is_offer_tuple = 1 THEN mri_session_id END) AS boost_seen_offer_sl, -- 8. Boosted offer tuple Confirm COUNT(DISTINCT CASE WHEN saw_boost = 1 AND is_offer_tuple = 1 AND has_confirm = 1 THEN mri_session_id END) AS boost_seen_offer_confirm FROM final WHERE exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2 ORDER BY 1, 2
